package org.usbworkbench;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class FatImageTest {
 static int checks;static void yes(boolean b){if(!b)throw new AssertionError();checks++;}
 static class Source implements OpticalImage.Source{RandomAccessFile file;Source(Path p)throws IOException{file=new RandomAccessFile(p.toFile(),"r");}public long size()throws IOException{return file.length();}public void read(long at,byte[] b,int off,int n)throws IOException{file.seek(at);file.readFully(b,off,n);}public void close()throws IOException{file.close();}}
 static class Sink implements OpticalImage.Sink{Map<String,ByteArrayOutputStream> files=new HashMap<>();public void directory(String path){}public OutputStream file(String path){ByteArrayOutputStream out=new ByteArrayOutputStream();files.put(path,out);return out;}public InputStream reopen(String path){return new ByteArrayInputStream(files.get(path).toByteArray());}}
 static void reject(OpticalImage.Source source,int part)throws Exception{try{FatImage.scan(source,part,(a,b)->{});throw new AssertionError("Expected unsafe image rejection");}catch(IOException e){yes(true);}}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);
  for(String name:new String[]{"fat16.img","fat32.img","fat16-mbr.img","fat32-mbr.img","fat16-gpt.img"})try(Source source=new Source(root.resolve(name))){OpticalImage.Manifest m=FatImage.scan(source,name.contains("-mbr")||name.contains("-gpt")?1:0,(a,b)->{});yes(m.entries.size()==4);yes(m.find("ملف عربي.txt").size==700);yes(m.find("DIR/INNER.TXT")!=null);Sink sink=new Sink();OpticalImage.extract(source,m,sink,(a,b)->{});byte[] original=new byte[700];for(int i=0;i<original.length;i++)original[i]=(byte)(i*7);yes(Arrays.equals(original,sink.files.get("ملف عربي.txt").toByteArray()));yes(new String(sink.files.get("DIR/INNER.TXT").toByteArray(),"UTF-8").equals("Owned nested FAT file\n"));yes(sink.files.get("EMPTY.TXT").size()==0);}
  try(Source source=new Source(root.resolve("fat16.img"))){byte[] raw=new byte[(int)source.size()];source.read(0,raw,0,raw.length);for(int variant=0;variant<7;variant++){byte[] b=raw.clone();int rootAt=(1+256)*512;if(variant==0)b[rootAt+13]^=1;if(variant==1){b[512+6]=3;b[512+7]=0;}if(variant==2)b[12]=0;if(variant==3){b[rootAt+32+28]=(byte)255;b[rootAt+32+29]=(byte)255;}if(variant==4){b[rootAt+32+26]=0;}if(variant==5){b[rootAt+1]=47;b[rootAt+2]=0;}if(variant==6)b[rootAt]=0x42;OpticalImage.Source broken=new OpticalImage.Source(){public long size(){return b.length;}public void read(long at,byte[] dst,int off,int n)throws IOException{if(at<0||n>b.length-at)throw new IOException("BOUNDS");System.arraycopy(b,(int)at,dst,off,n);}public void close(){}};reject(broken,0);}}
  try(Source source=new Source(root.resolve("fat16-mbr.img"))){reject(source,2);reject(source,129);}
  try(Source source=new Source(root.resolve("fat16.img"))){try{FatImage.scan(source,0,(a,b)->{throw new IOException("CANCELLED");});throw new AssertionError();}catch(IOException e){yes(e.getMessage().equals("CANCELLED"));}}
  System.out.println("PASS: "+checks+" FAT16/32 raw/MBR/GPT, fragmented Arabic LFN/nested/empty extraction, invalid metadata/chains/names/partition and cancellation checks");
 }
}
